create table if not exists public.profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, profile_data jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.import_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, source_type text not null, source_filename text not null, offer_count integer not null, created_at timestamptz not null default now());
create table if not exists public.job_offers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, import_session_id uuid not null references public.import_sessions(id) on delete cascade, external_id text not null, title text not null, company text not null, url text, normalized_data jsonb not null, created_at timestamptz not null default now(), unique(user_id, import_session_id, external_id));
create index if not exists import_sessions_user_id_idx on public.import_sessions(user_id); create index if not exists job_offers_user_id_idx on public.job_offers(user_id); create index if not exists job_offers_session_id_idx on public.job_offers(import_session_id);
alter table public.profiles enable row level security; alter table public.import_sessions enable row level security; alter table public.job_offers enable row level security;
create policy "profiles own rows" on public.profiles for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "import sessions own rows" on public.import_sessions for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "job offers own rows" on public.job_offers for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
